import torch

_DTYPE = {"int16": torch.int16, "int32": torch.int32, "int64": torch.int64, "int8": torch.int8, "uint8": torch.uint8}


def gen_inputs(ctx, device):
    a_shape = tuple(ctx["A__shape"])
    a_dtype = _DTYPE[ctx["A__dtype"]]
    b_shape = tuple(ctx["B__shape"])
    b_dtype = _DTYPE[ctx["B__dtype"]]
    A = torch.randint(low=1, high=100, size=a_shape, dtype=a_dtype, device=device)
    B = torch.randint(low=1, high=100, size=b_shape, dtype=b_dtype, device=device)
    return {"A": A, "B": B}


def run(A, B):
    A.gcd_(B)
    return A
